INSERT INTO pms_brands (id, name, first_letter, sort, factory_status, show_status, logo, big_pic, brand_story, created_at, updated_at, is_deleted, deleted_at) VALUES ('c8f131de-e83c-59b7-8c30-8204d514154f', '万和', 'W', '0', '1', '1', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20200607/5b07ca8aN4e127d2f.jpg', 'http://img13.360buyimg.com/cms/jfs/t1/121860/35/2430/187800/5ec4e294E22f3ffcc/1e233b65b94ba192.jpg', '万和成立于1993年8月，总部位于广东顺德国家级高新技术开发区内，是国内生产规模最大的燃气具专业制造企业，也是中国燃气具发展战略的首倡者和推动者、中国五金制品协会燃气用具分会第三届理事长单位。', '2026-06-19 06:04:07.881+00', '2026-06-19 06:04:07.881+00', false, NULL);
INSERT INTO pms_brands (id, name, first_letter, sort, factory_status, show_status, logo, big_pic, brand_story, created_at, updated_at, is_deleted, deleted_at) VALUES ('ca69a588-c4b5-5e86-a7db-cbff7b4cab24', '三星', 'S', '100', '1', '1', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20200607/57201b47N7bf15715.jpg', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20221108/sanxing_banner_01.png', '三星集团（英文：SAMSUNG、韩文：삼성）是韩国最大的跨国企业集团，三星集团包括众多的国际下属企业，旗下子公司有：三星电子、三星物产、三星人寿保险等，业务涉及电子、金融、机械、化学等众多领域。', '2026-06-19 06:04:07.881+00', '2026-06-19 06:04:07.881+00', false, NULL);
INSERT INTO pms_brands (id, name, first_letter, sort, factory_status, show_status, logo, big_pic, brand_story, created_at, updated_at, is_deleted, deleted_at) VALUES ('e4250db7-471a-5dd6-9fce-55a09f443a34', '华为', 'H', '100', '1', '1', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20200607/5abf6f26N31658aa2.jpg', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20221108/huawei_banner_01.png', '荣耀品牌成立于2013年,是华为旗下手机双品牌之一。荣耀以“创新、品质、服务”为核心战略,为全球年轻人提供潮酷的全场景智能化体验,打造年轻人向往的先锋文化和潮流生活方式', '2026-06-19 06:04:07.881+00', '2026-06-19 06:04:07.881+00', false, NULL);
