INSERT INTO pms_brands (id, name, first_letter, sort, factory_status, show_status, logo, big_pic, brand_story, created_at, updated_at, is_deleted, deleted_at) VALUES ('ed8286a9-9427-56a8-b5e1-a5dd75063169', '小米', 'M', '500', '1', '1', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20200607/5565f5a2N0b8169ae.jpg', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20221108/xiaomi_banner_01.png', '小米公司正式成立于2010年4月，是一家专注于高端智能手机、互联网电视自主研发的创新型科技企业。主要由前谷歌、微软、摩托、金山等知名公司的顶尖人才组建。', '2026-06-19 06:04:07.881+00', '2026-06-19 06:04:07.881+00', false, NULL);
INSERT INTO pms_brands (id, name, first_letter, sort, factory_status, show_status, logo, big_pic, brand_story, created_at, updated_at, is_deleted, deleted_at) VALUES ('931ee155-74bf-52f5-b288-accb6260913b', 'OPPO', 'O', '0', '1', '1', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20180607/timg(6).jpg', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20221108/oppo_banner_01.png', 'OPPO于2008年推出第一款“笑脸手机”，由此开启探索和引领至美科技之旅。今天，OPPO凭借以Find和R系列手机为核心的智能终端产品，以及OPPO+等互联网服务，让全球消费者尽享至美科技。', '2026-06-19 06:04:07.881+00', '2026-06-19 06:04:07.881+00', false, NULL);
