INSERT INTO pms_brands (id, name, first_letter, sort, factory_status, show_status, logo, big_pic, brand_story, created_at, updated_at, is_deleted, deleted_at) VALUES ('ca69a588-c4b5-5e86-a7db-cbff7b4cab24', '三星', 'S', '100', '1', '1', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20200607/57201b47N7bf15715.jpg', 'http://macro-oss.oss-cn-shenzhen.aliyuncs.com/mall/images/20221108/sanxing_banner_01.png', '三星集团（英文：SAMSUNG、韩文：삼성）是韩国最大的跨国企业集团，三星集团包括众多的国际下属企业，旗下子公司有：三星电子、三星物产、三星人寿保险等，业务涉及电子、金融、机械、化学等众多领域。', '2026-06-19 06:04:07.881+00', '2026-06-19 06:04:07.881+00', false, NULL);
